    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return datetime.fromisoformat(s)


def local_to_utc(naive, tz, dst=None):
    """dst: None -> first occurrence; True/False -> choose occurrence with that DST flag."""
    c0 = naive.replace(tzinfo=tz, fold=0)
    c1 = naive.replace(tzinfo=tz, fold=1)
    if c0.utcoffset() != c1.utcoffset() and dst is not None:
        for c in (c0, c1):
            if bool(c.dst()) == dst:
                return c.astimezone(UTC)
    return c0.astimezone(UTC)


def std_offset(tz):
    for m in (1, 7):
        d = datetime(2026, m, 1, tzinfo=tz)
        if not d.dst():
            return d.utcoffset()
    return datetime(2026, 1, 1, tzinfo=tz).utcoffset()


def parse_abbr(t, tz):
    out = []
    hdr = None
    for row in csv.reader(lines(t)):
        if 'Badge' in row and 'Punch' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]].strip()
        d = datetime.strptime(g('Date'), '%m/%d/%Y')
        ts = g('Time').upper()
        ampm = None
        if ts.endswith('AM') or ts.endswith('PM'):
            ampm = ts[-2:]
            ts = ts[:-2].strip()
        h, m, s = [int(x) for x in ts.split(':')]
        if ampm:
            h = h % 12 + (12 if ampm == 'PM' else 0)
        naive = d.replace(hour=h, minute=m, second=s)
        z = g('Zone').upper() if 'Zone' in hdr else ''
        dst = True if z.endswith('DT') else False if z.endswith('ST') else None
        out.append((g('Record'), g('Badge'), g('Punch').upper()[0], local_to_utc(naive, tz, dst)))
    return out


def parse_epoch(t, tz):
    out = []
    schema = 1
    for l in lines(t):
        o = json.loads(l)
        if 'schema' in o and 'heartbeat' not in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            if 'punch_id' not in o:
                continue
            ms = int(o['epoch_ms'])
            out.append((str(o['punch_id']), o['employee'], o['direction'].upper()[0],
                        datetime.fromtimestamp(ms // 1000, UTC)))
        else:
            if 'id' not in o:
                continue
            if 'ts_ms' in o:
                sec = int(o['ts_ms']) // 1000
            else:
                sec = int(o['ts'])
            out.append((str(o['id']), o['emp'], o['dir'].upper()[0], datetime.fromtimestamp(sec, UTC)))
    return out


def parse_offset(t, tz):
    out = []
    rows = list(csv.reader(lines(t), delimiter=';'))
    hdr = {n: i for i, n in enumerate(rows[0])}
    for r in rows[1:]:
        ev = r[hdr['event']]
        out.append((r[hdr['punch_id']], r[hdr['employee']], 'I' if ev == 'clock_in' else 'O',
                    iso(r[hdr['timestamp']]).astimezone(UTC)))
    return out


def parse_legacy(t, tz):
    out = []
    off = std_offset(tz)
    for l in t.replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        if not l.strip():
            continue
        k = l[0]
        if k == 'H':
            o = l[13:18].strip()
            if len(o) == 5 and o[0] in '+-':
                v = timedelta(hours=int(o[1:3]), minutes=int(o[3:5]))
                off = v if o[0] == '+' else -v
            else:
                off = std_offset(tz)
        elif k == 'D':
            pid = l[1:9]
            badge = 'E' + l[9:15].strip()
            d = l[15]
            dt = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            out.append((pid, badge, d, (dt - off).replace(tzinfo=UTC)))
    return out


