            continue
        g = lambda n: row[hdr[n]].strip()
        naive = datetime.strptime(g('Datum') + ' ' + g('Uhrzeit'), '%d.%m.%Y %H:%M')
        z = g('Zeitzone').upper() if 'Zeitzone' in hdr else ''
        dst = True if z == 'MESZ' else False if z == 'MEZ' else None
        out.append((g('Nr'), g('Ausweis'), 'I' if g('Buchung').upper() == 'K' else 'O',
                    local_to_utc(naive, tz, dst)))
    return out


def parse_localcsv(t, tz):
    out = []
    rows = list(csv.reader(lines(t)))
    hdr = {n.strip(): i for i, n in enumerate(rows[0])}
    for r in rows[1:]:
        naive = datetime.strptime(r[hdr['local_time']].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((r[hdr['punch_ref']].strip(), r[hdr['employee_id']].strip(),
                    r[hdr['direction']].strip().upper()[0], local_to_utc(naive, tz)))
    return out


def parse_localjsonl(t, tz):
    out = []
    for l in lines(t):
        o = json.loads(l)
        p = o.get('punch')
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], p['type'].upper()[0], local_to_utc(naive, tz)))
    return out


