           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def rnd(inst, tz):
    off = inst.astimezone(tz).utcoffset()
    local = inst + off
    secs = local.hour * 3600 + local.minute * 60 + local.second
    r = ((secs + 180) // 360) * 360
    return inst + timedelta(seconds=r - secs)


def main(indir, outfile):
    period = json.load(open(os.path.join(indir, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = iso(period['corrections_cutoff'])
    sites = {}
    with open(os.path.join(indir, 'sites.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = []
    home = {}
    with open(os.path.join(indir, 'employees.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            e = r['employee_id'].strip()
            emps.append(e)
            home[e] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(indir, 'rates.csv'), newline='', encoding='utf-8-sig') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    punches = {}  # (site,id) -> [emp, dir, instant]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(indir, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                for pid, emp, dr, inst in PARSERS[fmt](read_text(os.path.join(root, fn)), tz):
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, inst]

    corrs = []
    cdir = os.path.join(indir, 'corrections')
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                with io.StringIO(read_text(os.path.join(root, fn))) as s:
                    for r in csv.DictReader(s):
                        r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                        corrs.append(r)
    corrs = [c for c in corrs if iso(c['issued_at']) <= cutoff]
    corrs.sort(key=lambda c: (iso(c['issued_at']), c['correction_id']))
    applied = 0
    for c in corrs:
        k = (c['site'], c['punch_id'])
        a = c['action']
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = iso(c['time']).astimezone(UTC)
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [c['employee'], c['type'].upper()[0], iso(c['time']).astimezone(UTC)]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, inst) in punches.items():
        if emp in home:
            byemp.setdefault(emp, []).append((inst, 0 if dr == 'O' else 1, site, pid, dr))

    ex = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0) for e in emps}
    pay = {e: Fraction(0) for e in emps}

    for e, pl in byemp.items():
        hz = sites[home[e]][0]
        pl.sort()
        kept = []
        last = None
        for inst, _, site, pid, dr in pl:
            r = rnd(inst, sites[site][0])
            if last is not None and last[4] == dr and (inst - last[0]).total_seconds() <= 300:
                wd = r.astimezone(hz).date()
                if pstart <= wd <= pend:
                    ex['duplicates_dropped'] += 1
                continue
            last = (inst, 0, site, pid, dr)
            kept.append((r, dr, site))
        shifts = []
        i = 0
        n = len(kept)
        wdof = lambda r: r.astimezone(hz).date()
        while i < n:
            r, dr, site = kept[i]
            if dr == 'I':
                if i + 1 < n and kept[i + 1][1] == 'O' and \
                        (kept[i + 1][0] - r).total_seconds() <= 16 * 3600:
                    shifts.append((r, kept[i + 1][0], site))
                    i += 2
                    continue
                if pstart <= wdof(r) <= pend:
                    ex['open_shifts'] += 1
            else:
                if pstart <= wdof(r) <= pend:
                    ex['orphan_outs'] += 1
            i += 1
        shifts = [s for s in shifts if pstart <= wdof(s[0]) <= pend]
        shifts.sort(key=lambda s: s[0])
        daily = {}
        weekly = {}
        rt = rates.get(e, [])
        for rin, rout, site in shifts:
            tz = sites[site][0]
            wd = wdof(rin)
            worked = max(0, int((rout - rin).total_seconds() // 60))
            paid = worked - 30 if worked > 360 else worked
            # night
            night = 0
            ld = rin.astimezone(tz).date()
            for k in range(-1, 3):
                dd = ld + timedelta(days=k)
                ws = local_to_utc(datetime(dd.year, dd.month, dd.day, 22), tz)
                nd = dd + timedelta(days=1)
                we = local_to_utc(datetime(nd.year, nd.month, nd.day, 6), tz)
                a, b = max(ws, rin), min(we, rout)
                if b > a:
                    night += int((b - a).total_seconds() // 60)
            night = min(night, paid)
            used = daily.get(wd, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daily[wd] = used + paid
            wk = wd - timedelta(days=wd.weekday())
            nonot = paid - dot
            wu = weekly.get(wk, 0)
            wot = max(0, wu + nonot - 2400) - max(0, wu - 2400)
            weekly[wk] = wu + nonot
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rv in rt:
                if ef <= wd:
                    rate = rv
            if rate is None and rt:
                rate = rt[0][1]
            if rate is None:
                rate = Decimal(0)
            rf = Fraction(rate)
            pay[e] += rf * (reg + Fraction(3, 2) * ot) / 60 + rf * Fraction(15, 100) * night / 60
            d = res[e]
            d['shifts'] += 1
            d['paid_minutes'] += paid
            d['overtime_minutes'] += ot
            d['night_minutes'] += night

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totg = 0
    for e in emps:
        c = int(pay[e] * 100 + Fraction(1, 2) // 1) if False else int((pay[e] * 100 + Fraction(1, 2)) // 1)
        res[e]['gross'] = '%d.%02d' % (c // 100, c % 100)
        totg += c
        for k in tot:
            tot[k] += res[e][k]
    tot['gross'] = '%d.%02d' % (totg // 100, totg % 100)
    out = dict(period=dict(start=period['start'], end=period['end']), employees=res,
               exceptions=ex, totals=tot)
    with open(outfile, 'w') as f:
        json.dump(out, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
